PRAGMA journal_mode=MEMORY;
PRAGMA synchronous=FULL;
PRAGMA temp_store=MEMORY;
PRAGMA foreign_keys=ON;
PRAGMA trusted_schema=OFF;
PRAGMA application_id=1347832903;
PRAGMA user_version=1;
CREATE TABLE projection_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_schema TEXT NOT NULL CHECK(projection_schema='ergentics_ledger_projection_v1'),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),prose_may_supply_fact INTEGER NOT NULL CHECK(prose_may_supply_fact=0),unavailable_behavior TEXT NOT NULL CHECK(unavailable_behavior='NO_FINAL_DB_NO_STALE_FALLBACK_EMPTY_UI')) STRICT;
CREATE TABLE source_snapshot(source_sha256 TEXT PRIMARY KEY CHECK(length(source_sha256)=64),logical_path TEXT NOT NULL,git_commit TEXT NOT NULL CHECK(length(git_commit)=40),git_tree TEXT NOT NULL CHECK(length(git_tree)=40),git_blob TEXT NOT NULL CHECK(length(git_blob)=40),prefix_bytes INTEGER NOT NULL CHECK(prefix_bytes>=0),prefix_lf_count INTEGER NOT NULL CHECK(prefix_lf_count>=0),terminal_lf INTEGER NOT NULL CHECK(terminal_lf=1),raw_prefix BLOB NOT NULL CHECK(length(raw_prefix)=prefix_bytes)) STRICT,WITHOUT ROWID;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY CHECK(version>0),predecessor_version INTEGER,migration_name TEXT NOT NULL UNIQUE,ddl_sha256 TEXT NOT NULL CHECK(length(ddl_sha256)=64),transformer_sha256 TEXT NOT NULL CHECK(length(transformer_sha256)=64)) STRICT;
CREATE TABLE sections(source_sha256 TEXT NOT NULL REFERENCES source_snapshot(source_sha256),section_ordinal INTEGER NOT NULL CHECK(section_ordinal>0),heading_level INTEGER NOT NULL CHECK(heading_level BETWEEN 1 AND 6),heading_line INTEGER NOT NULL CHECK(heading_line>0),heading_byte_offset INTEGER NOT NULL CHECK(heading_byte_offset>=0),content_end_byte_offset INTEGER NOT NULL CHECK(content_end_byte_offset>=heading_byte_offset),heading_text TEXT NOT NULL,heading_sha256 TEXT NOT NULL CHECK(length(heading_sha256)=64),PRIMARY KEY(source_sha256,section_ordinal)) STRICT,WITHOUT ROWID;
CREATE TABLE appendix_records(record_ordinal INTEGER PRIMARY KEY CHECK(record_ordinal>0),source_sha256 TEXT NOT NULL REFERENCES source_snapshot(source_sha256),section_ordinal INTEGER,fence_ordinal INTEGER NOT NULL CHECK(fence_ordinal>0),ordinal_in_fence INTEGER NOT NULL CHECK(ordinal_in_fence>0),line_number INTEGER NOT NULL CHECK(line_number>0),byte_offset INTEGER NOT NULL CHECK(byte_offset>=0),byte_count INTEGER NOT NULL CHECK(byte_count>1),terminal_lf INTEGER NOT NULL CHECK(terminal_lf=1),raw_json BLOB NOT NULL CHECK(length(raw_json)=byte_count),raw_sha256_no_lf TEXT NOT NULL CHECK(length(raw_sha256_no_lf)=64),raw_sha256_with_lf TEXT NOT NULL CHECK(length(raw_sha256_with_lf)=64),canonical_state TEXT NOT NULL CHECK(canonical_state IN('CANONICAL_EXACT','PARSED_LEGACY_NONCANONICAL')),canonical_json_sha256 TEXT NOT NULL CHECK(length(canonical_json_sha256)=64),schema_text TEXT,status_text TEXT,payload_present INTEGER NOT NULL CHECK(payload_present IN(0,1)),payload_hash_rule_text TEXT,declared_payload_sha256 TEXT CHECK(declared_payload_sha256 IS NULL OR length(declared_payload_sha256)=64),computed_payload_sha256 TEXT CHECK(computed_payload_sha256 IS NULL OR length(computed_payload_sha256)=64),payload_hash_state TEXT NOT NULL CHECK(payload_hash_state IN('MATCH','ABSENT_DECLARATION','NOT_APPLICABLE')),UNIQUE(source_sha256,byte_offset),FOREIGN KEY(source_sha256,section_ordinal) REFERENCES sections(source_sha256,section_ordinal)) STRICT;
CREATE TABLE json_nodes(record_ordinal INTEGER NOT NULL REFERENCES appendix_records(record_ordinal),json_pointer TEXT NOT NULL,parent_pointer TEXT,child_ordinal INTEGER NOT NULL CHECK(child_ordinal>=0),node_kind TEXT NOT NULL CHECK(node_kind IN('OBJECT','ARRAY','STRING','NUMBER','BOOLEAN','JSON_NULL')),decoded_text TEXT,relative_byte_offset INTEGER NOT NULL CHECK(relative_byte_offset>=0),byte_count INTEGER NOT NULL CHECK(byte_count>0),raw_sha256 TEXT NOT NULL CHECK(length(raw_sha256)=64),child_count INTEGER NOT NULL CHECK(child_count>=0),PRIMARY KEY(record_ordinal,json_pointer)) STRICT,WITHOUT ROWID;
CREATE TABLE state_tokens(record_ordinal INTEGER NOT NULL,json_pointer TEXT NOT NULL,exact_value TEXT NOT NULL,state_class TEXT NOT NULL CHECK(state_class IN('PASS','FAIL','ABSTAIN')),classification_rule TEXT NOT NULL CHECK(classification_rule='EXACT_OR_UNDERSCORE_PREFIX_V1_PRESENTATION_ONLY'),canonical_source INTEGER NOT NULL CHECK(canonical_source IN(0,1)),PRIMARY KEY(record_ordinal,json_pointer),FOREIGN KEY(record_ordinal,json_pointer) REFERENCES json_nodes(record_ordinal,json_pointer)) STRICT,WITHOUT ROWID;
CREATE TABLE digest_occurrences(record_ordinal INTEGER NOT NULL,json_pointer TEXT NOT NULL,width_bits INTEGER NOT NULL CHECK(width_bits IN(160,256)),exact_hex TEXT NOT NULL,declared_algorithm TEXT CHECK(declared_algorithm IS NULL OR declared_algorithm='SHA256'),PRIMARY KEY(record_ordinal,json_pointer,exact_hex),FOREIGN KEY(record_ordinal,json_pointer) REFERENCES json_nodes(record_ordinal,json_pointer)) STRICT,WITHOUT ROWID;
CREATE TABLE graph_nodes(node_id TEXT PRIMARY KEY CHECK(length(node_id)=64),node_kind TEXT NOT NULL CHECK(node_kind IN('SOURCE','SECTION','RECORD','STATE','DIGEST')),canonical_key TEXT NOT NULL UNIQUE,display_label TEXT NOT NULL,record_ordinal INTEGER REFERENCES appendix_records(record_ordinal),json_pointer TEXT,authoritative INTEGER NOT NULL CHECK(authoritative=0)) STRICT,WITHOUT ROWID;
CREATE TABLE graph_edges(edge_id TEXT PRIMARY KEY CHECK(length(edge_id)=64),from_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),predicate TEXT NOT NULL CHECK(predicate IN('SOURCE_CONTAINS_SECTION','SECTION_CONTAINS_RECORD','RECORD_CONTAINS_STATE','RECORD_MENTIONS_DIGEST','RECORD_HASHES_TO','RECORD_WITH_LF_HASHES_TO','PAYLOAD_HASHES_TO')),to_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),source_record_ordinal INTEGER REFERENCES appendix_records(record_ordinal),source_json_pointer TEXT,evidence_grade TEXT NOT NULL CHECK(evidence_grade IN('STRUCTURAL_EXACT','COMPUTED_SHA256_EXACT','LEXICAL_EQUALITY_ONLY')),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0)) STRICT,WITHOUT ROWID;
CREATE TABLE projection_seal(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_id TEXT NOT NULL CHECK(length(projection_id)=64),source_sha256 TEXT NOT NULL REFERENCES source_snapshot(source_sha256),ddl_sha256 TEXT NOT NULL CHECK(length(ddl_sha256)=64),adapter_manifest_sha256 TEXT NOT NULL CHECK(length(adapter_manifest_sha256)=64),extractor_semantics_sha256 TEXT NOT NULL CHECK(length(extractor_semantics_sha256)=64),preseal_relational_export_sha256 TEXT NOT NULL CHECK(length(preseal_relational_export_sha256)=64),graph_export_sha256 TEXT NOT NULL CHECK(length(graph_export_sha256)=64),section_count INTEGER NOT NULL CHECK(section_count>=0),fence_count INTEGER NOT NULL CHECK(fence_count>=0),record_count INTEGER NOT NULL CHECK(record_count>=0),canonical_record_count INTEGER NOT NULL CHECK(canonical_record_count>=0),legacy_record_count INTEGER NOT NULL CHECK(legacy_record_count>=0),json_node_count INTEGER NOT NULL CHECK(json_node_count>=0),state_token_count INTEGER NOT NULL CHECK(state_token_count>=0),digest_occurrence_count INTEGER NOT NULL CHECK(digest_occurrence_count>=0),graph_node_count INTEGER NOT NULL CHECK(graph_node_count>=0),graph_edge_count INTEGER NOT NULL CHECK(graph_edge_count>=0)) STRICT;
CREATE VIEW presentation_authority_boundary AS SELECT authoritative,may_feed_controller,prose_may_supply_fact,authority_vector,unavailable_behavior FROM projection_policy WHERE singleton=1;
CREATE VIEW ui_timeline AS SELECT r.record_ordinal,r.line_number,s.heading_text AS section_title,r.schema_text,r.status_text,r.canonical_state,r.raw_sha256_no_lf,r.computed_payload_sha256,r.payload_hash_state FROM appendix_records r LEFT JOIN sections s ON s.source_sha256=r.source_sha256 AND s.section_ordinal=r.section_ordinal ORDER BY r.record_ordinal;
CREATE VIEW ui_state_tokens AS SELECT t.record_ordinal,t.json_pointer,t.exact_value,t.state_class,t.canonical_source FROM state_tokens t ORDER BY t.record_ordinal,t.json_pointer;
CREATE VIEW ui_graph_nodes AS SELECT node_id,node_kind,canonical_key,display_label,record_ordinal,json_pointer FROM graph_nodes WHERE authoritative=0 ORDER BY node_id;
CREATE VIEW ui_graph_edges AS SELECT edge_id,from_node_id,predicate,to_node_id,source_record_ordinal,source_json_pointer,evidence_grade FROM graph_edges WHERE authoritative=0 AND may_feed_controller=0 ORDER BY edge_id;
CREATE TRIGGER projection_policy_no_update BEFORE UPDATE ON projection_policy BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_policy_no_delete BEFORE DELETE ON projection_policy BEGIN SELECT RAISE(ABORT,'append-only'); END;
