CREATE TRIGGER source_snapshot_no_delete BEFORE DELETE ON source_snapshot BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER schema_migrations_no_update BEFORE UPDATE ON schema_migrations BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER schema_migrations_no_delete BEFORE DELETE ON schema_migrations BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER sections_no_update BEFORE UPDATE ON sections BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER sections_no_delete BEFORE DELETE ON sections BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER appendix_records_no_update BEFORE UPDATE ON appendix_records BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER appendix_records_no_delete BEFORE DELETE ON appendix_records BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER json_nodes_no_update BEFORE UPDATE ON json_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER json_nodes_no_delete BEFORE DELETE ON json_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER state_tokens_no_update BEFORE UPDATE ON state_tokens BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER state_tokens_no_delete BEFORE DELETE ON state_tokens BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER digest_occurrences_no_update BEFORE UPDATE ON digest_occurrences BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER digest_occurrences_no_delete BEFORE DELETE ON digest_occurrences BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_nodes_no_update BEFORE UPDATE ON graph_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_nodes_no_delete BEFORE DELETE ON graph_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_edges_no_update BEFORE UPDATE ON graph_edges BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_edges_no_delete BEFORE DELETE ON graph_edges BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_seal_no_update BEFORE UPDATE ON projection_seal BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_seal_no_delete BEFORE DELETE ON projection_seal BEGIN SELECT RAISE(ABORT,'append-only'); END;
